const GOOGLE_API_KEY = "xxx";


const distanceCache = {};

async function drivingDistance(lat1, lng1, lat2, lng2) {
  const key = `${lat1},${lng1}|${lat2},${lng2}`;
  if (distanceCache[key] !== undefined) return distanceCache[key];

  try {
    const result = await this.helpers.httpRequest({
      method: "POST",
      url: "https://routes.googleapis.com/directions/v2:computeRoutes",
      headers: {
        "Content-Type": "application/json",
        "X-Goog-Api-Key": GOOGLE_API_KEY,
        "X-Goog-FieldMask": "routes.distanceMeters"
      },
      body: {
        origin: {
          location: { latLng: { latitude: lat1, longitude: lng1 } }
        },
        destination: {
          location: { latLng: { latitude: lat2, longitude: lng2 } }
        },
        travelMode: "DRIVE",
        routingPreference: "TRAFFIC_UNAWARE"
      },
      json: true
    });

    if (!result.routes || result.routes.length === 0) throw new Error("No route");
    distanceCache[key] = result.routes[0].distanceMeters;
    return distanceCache[key];

  } catch (e) {
    const dLat = lat2 - lat1;
    const dLng = lng2 - lng1;
    const d = Math.sqrt(dLat * dLat + dLng * dLng) * 111000;
    distanceCache[key] = d;
    return d;
  }
}


async function totalCircularDistance(route) {
  let total = 0;
  for (let i = 0; i < route.length; i++) {
    const a = route[i];
    const b = route[(i + 1) % route.length]; // circolare: ultimo → primo
    total += await drivingDistance.call(this, a.LANG, a.LONG, b.LANG, b.LONG);
  }
  return total;
}

const items = $input.all();
const data = items[0].json;

const start = {
  row_number: 0,
  "NAME CARRIER": data["NAME CARRIER"],
  "DATE DELIVERY": data.deliveries[0]["DATE DELIVERY"],
  ADDRESS: data["START ADDRESS"],
  LANG: data["START LAT"],
  LONG: data["START LNG"]
};

const stops = data.deliveries.map(d => ({
  row_number: d.row_number,
  "NAME CARRIER": d["NAME CARRIER"],
  "DATE DELIVERY": d["DATE DELIVERY"],
  ADDRESS: d.ADDRESS,
  LANG: d.LANG,
  LONG: d.LONG
}));

let remaining = [...stops];
const route = [];
let currentLat = start.LANG;
let currentLng = start.LONG;

while (remaining.length > 0) {
  let bestIndex = 0;
  let bestCost = Infinity;

  const isLastStep = remaining.length === 1;

  const costs = await Promise.all(
    remaining.map(async (stop, i) => {
      // Distanza dal punto corrente al candidato
      const toCandidate = await drivingDistance.call(
        this, currentLat, currentLng, stop.LANG, stop.LONG
      );

      if (isLastStep) {
        // Ultimo step: considera anche il ritorno alla base
        const toBase = await drivingDistance.call(
          this, stop.LANG, stop.LONG, start.LANG, start.LONG
        );
        return toCandidate + toBase;
      }

      return toCandidate;
    })
  );

  for (let i = 0; i < costs.length; i++) {
    if (costs[i] < bestCost) {
      bestCost = costs[i];
      bestIndex = i;
    }
  }

  const nearest = remaining.splice(bestIndex, 1)[0];
  route.push(nearest);
  currentLat = nearest.LANG;
  currentLng = nearest.LONG;
}

let improved = true;
let iterations = 0;
const MAX_ITERATIONS = 100;

while (improved && iterations < MAX_ITERATIONS) {
  improved = false;
  iterations++;

  for (let i = 0; i < route.length - 1; i++) {
    for (let j = i + 1; j < route.length; j++) {

      const prevI = i === 0 ? start : route[i - 1];
      const nextJ = j === route.length - 1 ? start : route[j + 1];

      const currentCost =
        distanceCache[`${prevI.LANG},${prevI.LONG}|${route[i].LANG},${route[i].LONG}`] || 0 +
        distanceCache[`${route[j].LANG},${route[j].LONG}|${nextJ.LANG},${nextJ.LONG}`] || 0;

      // Dopo swap: ...→ route[j] → route[j-1] →...→ route[i] → route[j+1|base] →...
      const newCost =
        distanceCache[`${prevI.LANG},${prevI.LONG}|${route[j].LANG},${route[j].LONG}`] || 0 +
        distanceCache[`${route[i].LANG},${route[i].LONG}|${nextJ.LANG},${nextJ.LONG}`] || 0;

      if (newCost < currentCost) {
        // Inverti il segmento tra i e j
        const segment = route.slice(i, j + 1).reverse();
        route.splice(i, j - i + 1, ...segment);
        improved = true;
      }
    }
  }
}

const lastRowNumber = route[route.length - 1].row_number;

const returnToBase = {
  row_number: lastRowNumber + 1,
  "NAME CARRIER": data["NAME CARRIER"],
  "DATE DELIVERY": data.deliveries[0]["DATE DELIVERY"],
  ADDRESS: data["START ADDRESS"],
  LANG: data["START LAT"],
  LONG: data["START LNG"]
};

const ordered = [start, ...route, returnToBase];

return ordered.map(stop => ({ json: stop }));

const items = $input.all();

const grouped = {};

for (const item of items) {
  const carrier = item.json["NAME CARRIER"];

  if (!grouped[carrier]) {
    grouped[carrier] = [];
  }

  grouped[carrier].push(item.json);
}

// trasformo in array finale
const result = Object.keys(grouped).map(carrier => {
  return {
    json: {
      "NAME CARRIER": carrier,
      deliveries: grouped[carrier]
    }
  };
});

return result;

